lemma measurableRectangles.mem {s t : Set Ω}
    (hs : MeasurableSet s) (ht : MeasurableSet t) :
    s ×ˢ t ∈ measurableRectangles Ω

theorem momentPhi_congr_of_le {m : ℕ} (q : ℝ) {s t : ℕ → ℝ}
    (h : ∀ j ≤ m, s j = t j) :
    momentPhi m q s = momentPhi m q t

theorem eigenvalue_mem_halfInterval (A : E →L[ℝ] E) {lam : ℝ} {v : E}
    (hA : ‖A‖ ≤ (1 : ℝ) / 2) (hv : v ≠ 0) (heigen : A v = lam • v) :
    lam ∈ Set.Icc (-(1 : ℝ) / 2) (1 / 2)

lemma comp_rowBroadcast_eq_kernelOp {K : Omega -> Omega -> Real}
    (f : Omega -> Real) :
    comp mu K (fun z _y => f z) = fun x _y => kernelOp K mu f x

lemma goodK_memLp_prod_two {K : Omega -> Omega -> Real}
    (hK : GoodK K) :
    MemLp (Function.uncurry K) 2 (mu.prod mu)

lemma goodK_row {K : Omega -> Omega -> Real}
    (hK : GoodK K) (x : Omega) :
    Good (fun y => K x y)

lemma goodK_sub {K L : Omega -> Omega -> Real}
    (hK : GoodK K) (hL : GoodK L) :
    GoodK (fun x y => K x y - L x y)

lemma good_kernelOp_goodK {K : Omega -> Omega -> Real}
    (hK : GoodK K) {f : Omega -> Real} (hf : Good f) :
    Good (kernelOp K mu f)

lemma good_kernelSqRow {K : Omega -> Omega -> Real}
    (hK : GoodK K) :
    Good (fun x => ∫ y, K x y * K x y ∂mu)

lemma kernelOpGoodK_add' {K : Omega -> Omega -> Real}
    (hK : GoodK K) {f g : Omega -> Real}
    (hf : Good f) (hg : Good g) (x : Omega) :
    kernelOp K mu (f + g) x =
      kernelOp K mu f x + kernelOp K mu g x

lemma kernelOpGoodK_congr_ae {K : Omega -> Omega -> Real}
    {f g : Omega -> Real} (hfg : f =ᵐ[mu] g) :
    kernelOp K mu f = kernelOp K mu g

lemma kernelOpGoodK_memLp_two {K : Omega -> Omega -> Real}
    (hK : GoodK K) {f : Omega -> Real} (hf : Good f) :
    MemLp (kernelOp K mu f) 2 mu

lemma kernelOpGoodK_smul' {K : Omega -> Omega -> Real}
    (c : Real) (f : Omega -> Real) (x : Omega) :
    kernelOp K mu (c • f) x = c * kernelOp K mu f x

lemma kernelOpGoodK_sub_kernel' {K L : Omega -> Omega -> Real}
    (hK : GoodK K) (hL : GoodK L) {f : Omega -> Real}
    (hf : Good f) (x : Omega) :
    kernelOp (fun x y => K x y - L x y) mu f x =
      kernelOp K mu f x - kernelOp L mu f x

lemma kernelOp_congr_ae {f g : Omega -> Real}
    (hfg : f =ᵐ[mu] g) :
    kernelOp W mu f = kernelOp W mu g

lemma trace_finset_sum {ι : Type*} (s : Finset ι) {L : ι → Ω → Ω → ℝ}
    (hL : ∀ i ∈ s, GoodK (L i)) :
    trace μ (fun x y => ∑ i ∈ s, L i x y) = ∑ i ∈ s, trace μ (L i)

lemma kernelOp_finset_sum (hV : IsGraphon V μ) {ι : Type*} (s : Finset ι) {f : ι → Ω → ℝ}
    (hf : ∀ i ∈ s, Good (f i)) (x : Ω) :
    kernelOp V μ (fun y => ∑ i ∈ s, f i y) x = ∑ i ∈ s, kernelOp V μ (f i) x

lemma mul_le_max_zero {lambda t : Real}
    (hlambda : lambda ∈ Icc (0 : Real) 1) :
    lambda * t ≤ max t 0
